import * as tls from "node:tls";
import * as fs from "node:fs"; import * as os from "node:os"; import * as path from "node:path";
import { execFileSync } from "node:child_process";
const d = fs.mkdtempSync(path.join(os.tmpdir(), "r2c-tls-"));
execFileSync("openssl", ["req", "-x509", "-newkey", "rsa:2048", "-nodes", "-keyout", d + "/k.pem", "-out", d + "/c.pem", "-subj", "/CN=localhost", "-days", "1"], { stdio: "ignore" });
const cert = fs.readFileSync(d + "/c.pem");
const srv = tls.createServer({ key: fs.readFileSync(d + "/k.pem"), cert }, (s) => { s.on("data", (x) => s.end("echo:" + x)); });
function main(): void {
  srv.listen(0, "127.0.0.1", () => {
    const c = tls.connect({ port: (srv.address() as any).port, host: "127.0.0.1", ca: cert, servername: "localhost" }, () => {
      console.log(c.authorized, c.encrypted);
      c.write("hi");
    });
    c.setEncoding("utf8"); c.on("data", (x) => console.log(x)); c.on("close", () => { srv.close(); fs.rmSync(d, { recursive: true }); });
  });
}
